import {properties,state,filterProperties,money} from './data.js';
import {header,footer,icon,photo,button,specs,card,regionOptions,price,empty} from './ui.js';
export function matchPage(stage='intro'){const prefs=state.preferences;const candidates=filterProperties(properties,prefs).filter(p=>!state.likes.includes(p.id)&&!state.rejected.includes(p.id));const current=candidates[0];return `${header('match')}<main id="main" class="match-world"><div class="match-intro-copy"><span class="eyebrow">UM MATCH COM SEU PRÓXIMO CAPÍTULO</span><h1>Não é só<br>sobre morar.<br><span>É sobre você.</span></h1><p>Um novo jeito de descobrir um lugar<br>que faz sentido para o seu momento.</p><div class="match-instructions"><span>${icon('close')}Descarte o que não combina</span><span>${icon('heart')}Curta o que faz sentido</span><span>${icon('save')}Guarde para pensar depois</span></div><span class="demo-label">COMPATIBILIDADE SIMULADA</span></div><div class="match-device"><div class="device-top"><a href="#/match">${icon('back')}</a><b>Property Match<span class="notification-dot"></span></b><a href="#/match/lista" aria-label="Seus matches">${icon('heart')}</a></div>${stage==='intro'?`<div class="match-setup"><div class="step-line"><i class="active"></i><i></i><i></i></div><span class="eyebrow">01 / SUAS PREFERÊNCIAS</span><h2>Vamos encontrar<br>o seu lugar?</h2><p>Você conta o que importa.<br>A gente apresenta as possibilidades.</p><form id="match-preferences"><label>${icon('pin')}Região<select name="region">${regionOptions(prefs.region)}</select></label><label>${icon('home')}Modalidade<select name="mode"><option ${prefs.mode==='Alugar'?'selected':''}>Alugar</option><option ${prefs.mode==='Comprar'?'selected':''}>Comprar</option></select></label><label>${icon('filter')}Orçamento máximo<input type="number" min="500" step="50" name="max" value="${prefs.max}" required></label><label>${icon('bed')}Dormitórios<select name="beds">${[1,2,3].map(n=>`<option value="${n}" ${prefs.beds==n?'selected':''}>${n} ou mais</option>`).join('')}</select></label><label class="check-label"><input name="quiet" type="checkbox" ${prefs.quiet?'checked':''}>Prefiro ambientes com menor ruído</label><button class="btn green full">Começar o Match${icon('arrow')}</button></form><p class="micro">Suas preferências não alteram as informações dos imóveis. As avaliações territoriais são cadastradas pelos corretores.</p></div>`:stage==='lista'?`<div class="match-list"><span class="eyebrow">CONEXÕES QUE FAZEM SENTIDO</span><h2>Seus matches<span class="count">${state.likes.length}</span></h2><p>Imóveis que chamaram sua atenção.</p><div class="tabs"><button class="selected" data-match-tab="likes">Curtidos (${state.likes.length})</button><button data-match-tab="rejected">Descartados (${state.rejected.length})</button><button data-match-tab="favorites">Salvos</button></div><div id="match-list-items">${matchList('likes')}</div>${button('Continuar descobrindo','#/match/cards','green')}</div>`:current?`<div class="match-progress"><span>SELEÇÃO PARA VOCÊ</span><span>${candidates.length} possibilidades</span></div><article class="swipe-card">${photo(current.photo)}<span class="pill swipe-badge">${current.mode==='Alugar'?'Aluguel':'Venda'}</span><button class="favorite ${state.favorites.includes(current.id)?'active':''}" data-favorite="${current.id}" aria-label="Salvar ${current.name}">${icon('save')}</button><div class="swipe-content"><span class="compatibility">${icon('check')}${current.match}% de afinidade · simulação</span><h2>${current.name}</h2><strong class="price">${price(current)}</strong>${specs(current)}<div class="swipe-tags"><span>${icon('sound')}Ruído: ${current.noise.toLowerCase()}</span><span>${icon('pin')}${current.region}</span></div></div></article><div class="swipe-actions"><button data-decision="reject" data-id="${current.id}" aria-label="Descartar imóvel">${icon('close')}<span>Descartar</span></button><a href="#/imovel/${current.id}" aria-label="Ver detalhes">${icon('info')}<span>Detalhes</span></a><button data-decision="like" data-id="${current.id}" aria-label="Curtir imóvel">${icon('heart')}<span>Curtir</span></button></div><a class="match-adjust" href="#/match">Ajustar minhas preferências</a>`:`<div class="match-finished">${icon('check')}<h2>Você viu sua seleção.</h2><p>Reveja seus matches ou ajuste as preferências para explorar mais possibilidades.</p>${button('Ver meus matches','#/match/lista','green','heart')}${button('Ajustar preferências','#/match','outline','filter')}<button class="text-link" data-action="reset-match">Recomeçar esta seleção</button></div>`}<nav class="mobile-match-nav"><a href="#/">${icon('home')}Início</a><a class="selected" href="#/match/cards">${icon('layers')}Match</a><a href="#/match/lista">${icon('heart')}Matches</a><a href="#/favoritos">${icon('save')}Salvos</a></nav></div><div class="match-side-note"><span class="large-number">01—03</span><h3>Seu ritmo.<br>Sua escolha.</h3><p>Sem pressa, sem compromisso.<br>Explore a Zona Leste<br>de um jeito mais pessoal.</p><div class="bauhaus-tile"><i></i><i></i><i></i><i></i></div></div></main>${footer()}`;}
export function matchList(type){const items=properties.filter(p=>state[type].includes(p.id));return items.length?items.map(p=>`<article class="match-mini">${photo(p.photo)}<div><a href="#/imovel/${p.id}"><b>${p.name}</b></a><strong>${money(p.price)}${p.mode==='Alugar'?'<small>/mês</small>':''}</strong><span>${p.beds} dorms. · ${p.area} m²</span><button class="text-link" data-schedule="${p.id}">Agendar visita${icon('arrow')}</button></div></article>`).join(''):'<div class="empty small"><p>Nenhum imóvel nesta seleção ainda.</p></div>';}
